package com.myassist.customer.ui;
import android.content.Intent;import android.os.Bundle;import android.widget.TextView;import androidx.appcompat.app.AppCompatActivity;import com.myassist.customer.MyAssistApp;
public class HomeActivity extends AppCompatActivity{protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_home);((TextView)findViewById(R.id.tvWelcome)).setText("Welcome, "+MyAssistApp.session().fullName());findViewById(R.id.btnCreate).setOnClickListener(v->startActivity(new Intent(this,CreateRequestActivity.class)));findViewById(R.id.btnOrders).setOnClickListener(v->startActivity(new Intent(this,TrackOrdersActivity.class)));findViewById(R.id.btnProfile).setOnClickListener(v->startActivity(new Intent(this,ProfileActivity.class)));}}